<?php

declare(strict_types=1);

namespace App\Calls\Processes;

use App\Contracts\Domains\CallSender;
use App\Data\Processes\ExplanationData;
use App\Enums\OutputStream;
use App\Enums\ShellDialect;
use App\Support\CallKey;
use App\Values\RunEvent;

/**
 * The signed calls of Processes, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class ProcessCalls
{
    public function __construct(private CallSender $sender) {}

    public function admitLine(
        string $line,
        ShellDialect $dialect,
        string $workingFolder,
        CallKey $requestKey = new CallKey(),
    ): LineAdmitted {
        return $this->sender->send(AdmitLineCall::from([
            'line' => $line,
            'dialect' => $dialect,
            'workingFolder' => $workingFolder,
            'requestKey' => $requestKey,
        ]));
    }

    public function approveProposal(
        string $proposal,
        int $expectedRevision,
        int $expectedActiveRevision,
        string|null $readerRevision,
        string|null $proof,
        string $reason,
        CallKey $requestKey = new CallKey(),
    ): RuleApproved {
        return $this->sender->send(ApproveProposalCall::from([
            'proposal' => $proposal,
            'expectedRevision' => $expectedRevision,
            'expectedActiveRevision' => $expectedActiveRevision,
            'readerRevision' => $readerRevision,
            'proof' => $proof,
            'reason' => $reason,
            'requestKey' => $requestKey,
        ]));
    }

    public function approveSample(
        string $commandRequest,
        int $expectedRevision,
        string $commandDigest,
        CallKey $requestKey = new CallKey(),
    ): SampleApproved {
        return $this->sender->send(ApproveSampleCall::from([
            'commandRequest' => $commandRequest,
            'expectedRevision' => $expectedRevision,
            'commandDigest' => $commandDigest,
            'requestKey' => $requestKey,
        ]));
    }

    public function checkRestoredOutput(
        string $processRun,
        CallKey $requestKey = new CallKey(),
    ): RestoreChecked {
        return $this->sender->send(CheckRestoredOutputCall::from([
            'processRun' => $processRun,
            'requestKey' => $requestKey,
        ]));
    }

    public function checkRunCurrency(
        string $processRun,
        string $eventKey,
    ): RunCurrency {
        return $this->sender->send(CheckRunCurrencyCall::from([
            'processRun' => $processRun,
            'eventKey' => $eventKey,
        ]));
    }

    /**
     * @param  list<string>  $runs
     */
    public function cleanOutput(
        array $runs,
        bool $preview,
        CallKey $requestKey = new CallKey(),
    ): OutputCleaned {
        return $this->sender->send(CleanOutputCall::from([
            'runs' => $runs,
            'preview' => $preview,
            'requestKey' => $requestKey,
        ]));
    }

    public function explainCommand(
        string $line,
        ShellDialect $dialect = ShellDialect::Bash,
    ): ExplanationData {
        return $this->sender->send(ExplainCommandCall::from([
            'line' => $line,
            'dialect' => $dialect,
        ]));
    }

    public function fetchAdmission(
        string $processRun,
        CallKey $requestKey = new CallKey(),
    ): AdmissionFetched {
        return $this->sender->send(FetchAdmissionCall::from([
            'processRun' => $processRun,
            'requestKey' => $requestKey,
        ]));
    }

    public function importProposals(
        string $declarations,
        CallKey $requestKey = new CallKey(),
    ): ProposalsImported {
        return $this->sender->send(ImportProposalsCall::from([
            'declarations' => $declarations,
            'requestKey' => $requestKey,
        ]));
    }

    /**
     * @param  list<string>  $states
     */
    public function listProposals(
        array $states = [],
    ): ProposalList {
        return $this->sender->send(ListProposalsCall::from([
            'states' => $states,
        ]));
    }

    /**
     * @param  array<string, mixed>  $definition
     */
    public function proposeReader(
        string $commandRequest,
        int $declarationRevision,
        array $definition,
    ): ReaderProposed {
        return $this->sender->send(ProposeReaderCall::from([
            'commandRequest' => $commandRequest,
            'declarationRevision' => $declarationRevision,
            'definition' => $definition,
        ]));
    }

    /**
     * @param  array<string, mixed>  $declaration
     */
    public function proposeRule(
        string $commandRequest,
        array $declaration,
        CallKey $requestKey = new CallKey(),
    ): ProposalReceived {
        return $this->sender->send(ProposeRuleCall::from([
            'commandRequest' => $commandRequest,
            'declaration' => $declaration,
            'requestKey' => $requestKey,
        ]));
    }

    /**
     * @param  list<string>  $runs
     */
    public function proveReader(
        string $commandRequest,
        string $readerRevision,
        array $runs,
        CallKey $requestKey = new CallKey(),
    ): ReaderProofStarted {
        return $this->sender->send(ProveReaderCall::from([
            'commandRequest' => $commandRequest,
            'readerRevision' => $readerRevision,
            'runs' => $runs,
            'requestKey' => $requestKey,
        ]));
    }

    public function readOutputBytes(
        string $processRun,
        int $part = 0,
        OutputStream $stream = OutputStream::Stdout,
    ): OutputBytes {
        return $this->sender->send(ReadOutputBytesCall::from([
            'processRun' => $processRun,
            'part' => $part,
            'stream' => $stream,
        ]));
    }

    public function readOutputSummary(
        string $processRun,
    ): OutputSummary {
        return $this->sender->send(ReadOutputSummaryCall::from([
            'processRun' => $processRun,
        ]));
    }

    public function readOutputTail(
        string $processRun,
        int $part = 0,
        OutputStream $stream = OutputStream::Stdout,
        int $lines = 20,
    ): OutputTail {
        return $this->sender->send(ReadOutputTailCall::from([
            'processRun' => $processRun,
            'part' => $part,
            'stream' => $stream,
            'lines' => $lines,
        ]));
    }

    public function recordRunChunk(
        string $processRun,
        string $eventKey,
        RunChunk $chunk,
    ): ChunkStored {
        return $this->sender->send(RecordRunChunkCall::from([
            'processRun' => $processRun,
            'eventKey' => $eventKey,
            'chunk' => $chunk,
        ]));
    }

    /**
     * @param  list<RunEvent>  $events
     */
    public function recordRunEvents(
        string $processRun,
        string $eventKey,
        array $events,
    ): RunEventsAccepted {
        return $this->sender->send(RecordRunEventsCall::from([
            'processRun' => $processRun,
            'eventKey' => $eventKey,
            'events' => $events,
        ]));
    }

    public function rejectProposal(
        string $proposal,
        string $reason,
        CallKey $requestKey = new CallKey(),
    ): ProposalStateChanged {
        return $this->sender->send(RejectProposalCall::from([
            'proposal' => $proposal,
            'reason' => $reason,
            'requestKey' => $requestKey,
        ]));
    }

    public function restoreRule(
        string $rule,
        int $fromRevision,
        int $expectedRevision,
        CallKey $requestKey = new CallKey(),
    ): ProposalReceived {
        return $this->sender->send(RestoreRuleCall::from([
            'rule' => $rule,
            'fromRevision' => $fromRevision,
            'expectedRevision' => $expectedRevision,
            'requestKey' => $requestKey,
        ]));
    }

    public function retireRule(
        string $rule,
        int $expectedRevision,
        string $reason,
        CallKey $requestKey = new CallKey(),
    ): RuleRetired {
        return $this->sender->send(RetireRuleCall::from([
            'rule' => $rule,
            'expectedRevision' => $expectedRevision,
            'reason' => $reason,
            'requestKey' => $requestKey,
        ]));
    }

    /**
     * @param  array<string, mixed>  $declaration
     */
    public function reviseProposal(
        string $proposal,
        array $declaration,
        int|null $expectedRevision,
        CallKey $requestKey = new CallKey(),
    ): ProposalReceived {
        return $this->sender->send(ReviseProposalCall::from([
            'proposal' => $proposal,
            'declaration' => $declaration,
            'expectedRevision' => $expectedRevision,
            'requestKey' => $requestKey,
        ]));
    }

    public function searchOutput(
        string $text,
        string $processRun,
        int $part = 0,
        OutputStream $stream = OutputStream::Stdout,
    ): OutputMatches {
        return $this->sender->send(SearchOutputCall::from([
            'text' => $text,
            'processRun' => $processRun,
            'part' => $part,
            'stream' => $stream,
        ]));
    }

    public function settleSample(
        string $commandRequest,
        CallKey $requestKey = new CallKey(),
    ): SampleSettled {
        return $this->sender->send(SettleSampleCall::from([
            'commandRequest' => $commandRequest,
            'requestKey' => $requestKey,
        ]));
    }

    public function showCommandRequest(
        string $commandRequest,
    ): CommandRequestShown {
        return $this->sender->send(ShowCommandRequestCall::from([
            'commandRequest' => $commandRequest,
        ]));
    }

    public function startEvidenceRun(
        string $evidencePermit,
        CallKey $requestKey = new CallKey(),
    ): EvidenceRunStarted {
        return $this->sender->send(StartEvidenceRunCall::from([
            'evidencePermit' => $evidencePermit,
            'requestKey' => $requestKey,
        ]));
    }

    public function startSample(
        string $commandRequest,
        string $permit,
        CallKey $requestKey = new CallKey(),
    ): SampleStarted {
        return $this->sender->send(StartSampleCall::from([
            'commandRequest' => $commandRequest,
            'permit' => $permit,
            'requestKey' => $requestKey,
        ]));
    }

    public function withdrawProposal(
        string $proposal,
        CallKey $requestKey = new CallKey(),
    ): ProposalStateChanged {
        return $this->sender->send(WithdrawProposalCall::from([
            'proposal' => $proposal,
            'requestKey' => $requestKey,
        ]));
    }
}
